#!/usr/bin/env python3
"""Build W9 additive exports using the unchanged canonical W5 exporter."""
from pathlib import Path
import json, shutil, hashlib, importlib.util, copy
ROOT=Path(__file__).resolve().parent
BASE=ROOT.parent/'playlist-mixed-w8/canonical'
def digest(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def put(p,v):
 p=ROOT/p;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(v)
def run():
 if not (ROOT/'canonical').exists(): shutil.copytree(BASE,ROOT/'canonical')
 if not (ROOT/'tools/build_tokens.py').exists():
  (ROOT/'tools').mkdir(exist_ok=True);shutil.copy2(ROOT.parent/'scripts/build_tokens.py',ROOT/'tools/build_tokens.py')
 spec=importlib.util.spec_from_file_location('canonical_exporter',ROOT/'tools/build_tokens.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
 base=json.loads((ROOT/'canonical/tokens/soundq.tokens.json').read_text())
 # Light is an additive semantic overlay. Primitive brand values remain intact.
 colors={'background':'F8F4EB','surface':'F0E9DD','raised':'E6DCCD','text':'211A13','textMuted':'625749','border':'8B7C69','borderInput':'786955','disabledBackground':'E6DED2','disabledBorder':'A99B87','disabledText':'756957','error':'A52A20','focus':'006C65','hover':'DFD4C3','primary':'B63D00','primaryHover':'943200','progressTrack':'8B7C69','secondary':'006C65','selected':'B63D00','subtleBorder':'D1C4B1','art':'E6DCCD','scrim':'000000'}
 overlay={'$description':'W9 Light only; merge over immutable W5. No dynamic color or primitive replacement.','semantic':{'color':{k:{'$type':'color','$value':{'colorSpace':'srgb','components':[int(v[i:i+2],16)/255 for i in (0,2,4)],'hex':'#'+v}} for k,v in colors.items()}},'component':{}}
 comp={'button':{'disabledBackground':'disabledBackground','disabledText':'disabledText','primaryBackground':'primary','primaryHover':'primaryHover'},'navigation':{'selectedText':'selected'},'player':{'background':'raised','progress':'primary'},'row':{'currentBackground':'surface','currentTitle':'primary','selectedBorder':'selected'},'search':{'border':'borderInput','focus':'focus'},'sheet':{'background':'surface'}}
 for group,roles in comp.items(): overlay['component'][group]={k:{'$type':'color','$value':'{semantic.color.'+v+'}'} for k,v in roles.items()}
 overlay['component']['button']['primaryText']={'$type':'color','$value':'{primitive.color.ink}'}
 roles={'selectionBackground':'surface','selectionText':'primary','rowRevealBackground':'secondary','rowRevealText':'background','waveformBase':'textMuted','waveformBeat':'secondary','waveformPlayhead':'primary','waveformSelection':'secondary','waveformDeck':'surface','waveformCue':'primary','waveformOrigin':'text','compactPlayerBackground':'raised','compactPlayerText':'text','sheetBackground':'surface','sheetScrim':'scrim','inputBackground':'background','inputBorder':'borderInput','inputHover':'hover','inputFocus':'focus','buttonPressed':'secondary','buttonHover':'hover','buttonSelected':'selected','buttonOnPressed':'background'}
 extension={'w9':{'color':{k:{'$type':'color','$value':'{semantic.color.'+v+'}'} for k,v in roles.items()}}}
 def merge(a,b):
  for k,v in b.items():
   if isinstance(v,dict) and '$value' not in v and isinstance(a.get(k),dict): merge(a[k],v)
   else:a[k]=copy.deepcopy(v)
  return a
 put('tokens/light.overlay.json',json.dumps(overlay,indent=2)+'\n');put('tokens/shared.roles.json',json.dumps(extension,indent=2)+'\n')
 resolved={}
 for mode in ('dark','light'):
  doc=merge(copy.deepcopy(base),extension)
  if mode=='light':merge(doc,overlay)
  outputs=m.render(doc)
  for name in ('tokens.css','SoundQComposeTokens.kt'):
   text=outputs[name].replace('object SoundQComposeTokens {','object SoundQ'+mode.title()+'Tokens {').replace('Generated from tokens/soundq.tokens.json','Generated by W9 build.py: immutable canonical + shared.roles + optional light.overlay')
   if name.endswith('.css'):text=text.replace(':root {','[data-theme="'+mode+'"] {')
   put('generated/'+mode+'.'+name,text)
  resolved[mode]={k:m.normalized(*v) for k,v in m.resolve(doc).items()}
 put('generated/resolved.json',json.dumps(resolved,indent=2)+'\n')
 colorpaths=[k for k in resolved['dark'] if k.startswith(('semantic.color.','component.','w9.color.')) and isinstance(resolved['dark'][k],str) and resolved['dark'][k].startswith('#')]
 kt=['// Generated W9 role adapter; design input, not compiled native acceptance.','package soundq.design.generated','import androidx.compose.ui.graphics.Color','enum class SoundQAppearance { System, Light, Dark }','data class SoundQModeColors(']+['    val '+m.identifier(k,'_')+': Color,' for k in colorpaths]+[')','object SoundQAppearanceMapping {']
 for mode in ('dark','light'):
  kt+=['    val '+mode+' = SoundQModeColors(']+['        '+m.identifier(k,'_')+' = SoundQ'+mode.title()+'Tokens.'+m.identifier(k,'_').upper()+',' for k in colorpaths]+['    )']
 kt+=['    fun resolve(choice: SoundQAppearance, systemDark: Boolean): SoundQModeColors =','        if (choice == SoundQAppearance.Dark || (choice == SoundQAppearance.System && systemDark)) dark else light','}']
 put('generated/SoundQAppearanceMapping.kt','\n'.join(kt)+'\n')
 inputs={str(p.relative_to(ROOT.parent.parent.parent.parent)):digest(p) for p in BASE.rglob('*') if p.is_file()}
 inputs[str(ROOT.parent/'scripts/build_tokens.py')]=digest(ROOT.parent/'scripts/build_tokens.py')
 put('INPUTS.json',json.dumps({'owner':'Hotate / hotate-design','readOnlyInputs':inputs,'canonicalCopyByteExact':all(digest(p)==digest(ROOT/'canonical'/p.relative_to(BASE)) for p in BASE.rglob('*') if p.is_file())},indent=2)+'\n')
 print(json.dumps({'modes':list(resolved),'tokensPerMode':{k:len(v) for k,v in resolved.items()},'canonicalCopiesUnchanged':True}))
if __name__=='__main__':run()
